{
  "$schema": "https://opencode.ai/v2/config.json",
  "model": "ollama/qwen3:1.7b",
  "default_agent": "build",
  "update": "disable",
  "share": "disabled",
  "warming": false,
  "snapshots": false,
  "formatter": false,
  "lsp": false,
  "compaction": {
    "auto": false
  },
  "instructions": [],
  "plugins": [],
  "mcp": {},
  "skills": [
    "/skills"
  ],
  "permissions": [
    {
      "action": "*",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "read",
      "resource": ".",
      "effect": "allow"
    },
    {
      "action": "read",
      "resource": "docs",
      "effect": "allow"
    },
    {
      "action": "read",
      "resource": "docs/ADR-021.md",
      "effect": "allow"
    },
    {
      "action": "read",
      "resource": "/skills/adk-adr-writer/*",
      "effect": "allow"
    },
    {
      "action": "external_directory",
      "resource": "/skills/adk-adr-writer/*",
      "effect": "allow"
    },
    {
      "action": "edit",
      "resource": "docs/ADR-021.md",
      "effect": "allow"
    },
    {
      "action": "glob",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "grep",
      "resource": "*",
      "effect": "allow"
    },
    {
      "action": "skill",
      "resource": "adk-adr-writer",
      "effect": "allow"
    }
  ],
  "policies": [
    {
      "action": "provider.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "integration.connect",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "integration.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "mcp.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "plugin.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "websearch.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "skill.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "tool.use",
      "resource": "*",
      "effect": "deny"
    },
    {
      "action": "provider.use",
      "resource": "ollama",
      "effect": "allow"
    },
    {
      "action": "integration.use",
      "resource": "ollama",
      "effect": "allow"
    },
    {
      "action": "skill.use",
      "resource": "adk-adr-writer",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "read:*",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "edit:*",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "glob:*",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "grep:*",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "skill:adk-adr-writer",
      "effect": "allow"
    },
    {
      "action": "tool.use",
      "resource": "external_directory:/skills/adk-adr-writer/*",
      "effect": "allow"
    }
  ],
  "agents": {
    "build": {
      "model": "ollama/qwen3:1.7b",
      "steps": 20
    },
    "general": {
      "disabled": true
    },
    "explore": {
      "disabled": true
    },
    "title": {
      "disabled": true
    },
    "summary": {
      "disabled": true
    },
    "compaction": {
      "disabled": true
    }
  },
  "providers": {
    "ollama": {
      "name": "Task-local Ollama",
      "package": "@opencode/ai/providers/openai-compatible",
      "env": [],
      "settings": {
        "baseURL": "http://127.0.0.1:11439/v1",
        "apiKey": false,
        "provider": "ollama"
      },
      "models": {
        "qwen3:1.7b": {
          "name": "qwen3:1.7b",
          "capabilities": {
            "tools": true,
            "input": [
              "text"
            ],
            "output": [
              "text"
            ],
            "temperature": true
          },
          "limit": {
            "context": 16384,
            "output": 4096
          },
          "body": {
            "temperature": 0,
            "seed": 20261114
          }
        }
      }
    }
  },
  "experimental": {
    "subagent_depth": 0
  }
}
